package com.awesomeclan.roster;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;

public final class RosterCollector
{
	private static final String DEFAULT_CLAN_NAME = "AwesomeClan";

	private RosterCollector()
	{
	}

	public static RosterPayload collect(ClanSettings clanSettings)
	{
		Map<String, Integer> hierarchy = new LinkedHashMap<>();
		for (int i = -1; i <= 127; i++)
		{
			String name = rankName(clanSettings, new ClanRank(i));
			if (name != null)
			{
				hierarchy.put(name, i);
			}
		}

		List<RosterMember> members = new ArrayList<>();
		for (ClanMember member : clanSettings.getMembers())
		{
			String name = normalizeName(member.getName());
			if (name == null || name.isEmpty())
			{
				continue;
			}

			ClanRank rank = member.getRank();
			int rankId = rank == null ? 0 : rank.getRank();
			members.add(new RosterMember(name, rankName(clanSettings, rank), rankId));
		}

		String clanName = normalizeName(clanSettings.getName());
		if (clanName == null || clanName.isEmpty())
		{
			clanName = DEFAULT_CLAN_NAME;
		}

		return new RosterPayload(clanName, members, hierarchy);
	}

	private static String rankName(ClanSettings clanSettings, ClanRank rank)
	{
		if (rank == null)
		{
			return null;
		}

		ClanTitle title = clanSettings.titleForRank(rank);
		if (title != null && title.getName() != null && !title.getName().isEmpty())
		{
			return title.getName();
		}

		if (rank.equals(ClanRank.OWNER))
		{
			return "Owner";
		}
		if (rank.equals(ClanRank.DEPUTY_OWNER))
		{
			return "Deputy Owner";
		}
		if (rank.equals(ClanRank.ADMINISTRATOR))
		{
			return "Administrator";
		}
		if (rank.equals(ClanRank.JMOD))
		{
			return "Jagex Moderator";
		}
		if (rank.equals(ClanRank.GUEST))
		{
			return "Guest";
		}

		return "Rank " + rank.getRank();
	}

	private static String normalizeName(String name)
	{
		if (name == null)
		{
			return null;
		}

		String normalized = name.replace(' ', ' ').replace('�', ' ').trim();
		return normalized.replaceAll("\\s+", " ");
	}
}

package com.awesomeclan;

import com.awesomeclan.api.ApiClient;
import com.awesomeclan.clan.ClanBroadcastTracker;
import com.awesomeclan.clan.CofferBalanceReader;
import com.awesomeclan.live.LiveDataTracker;
import com.awesomeclan.roster.RosterCollector;
import com.google.inject.Provides;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanSettings;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;

@PluginDescriptor(
	name = "AwesomeClan",
	description = "Keeps the AwesomeClan roster synced with the clan website, and optionally shows your XP/boss kills live on the dashboard while you play",
	tags = {"clan", "roster", "awesomeclan"}
)
public class AwesomeClanPlugin extends Plugin
{
	public static final String CLAN_NAME = "AwesomeClan";

	private static final int SYNC_INTERVAL_MINUTES = 20;
	private static final int SYNC_JITTER_MINUTES = 10;
	private static final int LIVE_FLUSH_PERIOD_SECONDS = 15;

	@Inject
	private Client client;

	@Inject
	private ApiClient api;

	@Inject
	private EventBus eventBus;

	@Inject
	private LiveDataTracker liveDataTracker;

	@Inject
	private ClanBroadcastTracker clanBroadcastTracker;

	@Inject
	private CofferBalanceReader cofferBalanceReader;

	private Instant nextSyncAt;

	@Provides
	AwesomeClanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AwesomeClanConfig.class);
	}

	@Override
	protected void startUp()
	{
		nextSyncAt = nextSyncTime();
		eventBus.register(liveDataTracker);
		eventBus.register(clanBroadcastTracker);
		eventBus.register(cofferBalanceReader);
	}

	@Override
	protected void shutDown()
	{
		nextSyncAt = null;
		liveDataTracker.flushOnShutdown();
		eventBus.unregister(liveDataTracker);
		eventBus.unregister(clanBroadcastTracker);
		eventBus.unregister(cofferBalanceReader);
		liveDataTracker.reset();
	}

	@Schedule(period = LIVE_FLUSH_PERIOD_SECONDS, unit = ChronoUnit.SECONDS)
	public void flushLiveData()
	{
		liveDataTracker.flushPeriodic();
	}

	@Schedule(period = 5, unit = ChronoUnit.MINUTES)
	public void trySync()
	{
		if (nextSyncAt == null || Instant.now().isBefore(nextSyncAt))
		{
			return;
		}

		nextSyncAt = nextSyncTime();

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		ClanSettings clanSettings = client.getClanSettings();
		if (clanSettings == null || clanSettings.getMembers() == null || clanSettings.getMembers().isEmpty())
		{
			return;
		}

		if (!CLAN_NAME.equalsIgnoreCase(clanSettings.getName()))
		{
			return;
		}

		api.post("clan/roster", RosterCollector.collect(clanSettings));
	}

	public static boolean inClan(Client client)
	{
		ClanChannel channel = client.getClanChannel();
		return channel != null && CLAN_NAME.equalsIgnoreCase(channel.getName());
	}

	private static Instant nextSyncTime()
	{
		int jitterSeconds = ThreadLocalRandom.current().nextInt(0, SYNC_JITTER_MINUTES * 60);
		return Instant.now().plusSeconds(SYNC_INTERVAL_MINUTES * 60L + jitterSeconds);
	}
}

package com.awesomeclan.clan;

import com.awesomeclan.AwesomeClanPlugin;
import com.awesomeclan.api.ApiClient;
import javax.inject.Inject;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Sends the real coffer balance when someone opens the clan coffer, to fix up
 * the running total if a deposit/withdraw broadcast was missed.
 */
public class CofferBalanceReader
{
	@Inject
	private Client client;

	@Inject
	private ApiClient api;

	private int readDelay = -1;

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CLANS_STORAGE_MAIN)
		{
			// items aren't populated on the tick the widget loads
			readDelay = 2;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (readDelay < 0 || --readDelay > 0)
		{
			return;
		}
		readDelay = -1;

		if (!AwesomeClanPlugin.inClan(client))
		{
			return;
		}

		Widget items = client.getWidget(InterfaceID.ClansStorageMain.ITEMS);
		if (items == null || items.getDynamicChildren() == null)
		{
			return;
		}

		for (Widget child : items.getDynamicChildren())
		{
			if (child.getItemId() == ItemID.COINS)
			{
				api.post("clan/coffer-balance", new CofferBalance(AwesomeClanPlugin.CLAN_NAME, child.getItemQuantity()));
				return;
			}
		}
	}

	@Value
	private static class CofferBalance
	{
		String clanName;
		long balance;
	}
}

package com.awesomeclan.clan;

import com.awesomeclan.AwesomeClanPlugin;
import com.awesomeclan.api.ApiClient;
import com.awesomeclan.util.AccountId;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Reports clan broadcasts for kicks, recruits and coffer deposits/withdrawals.
 * Every online member gets these, so they're picked up even if the person
 * doing the kicking/depositing doesn't run the plugin.
 */
@Slf4j
public class ClanBroadcastTracker
{
	private static final Pattern KICK = Pattern.compile("^(.+?) has expelled (.+?) from the clan\\.$");
	private static final Pattern RECRUIT = Pattern.compile("^(.+?) has been invited into the clan by (.+?)\\.?$");
	private static final Pattern DEPOSIT = Pattern.compile("^(.+?) has deposited ([0-9,]+) coins? into the coffer\\.$");
	private static final Pattern WITHDRAW = Pattern.compile("^(.+?) has withdrawn ([0-9,]+) coins? from the coffer\\.$");

	@Inject
	private Client client;

	@Inject
	private ApiClient api;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.CLAN_MESSAGE || !AwesomeClanPlugin.inClan(client))
		{
			return;
		}

		String message = Text.removeTags(event.getMessage()).trim();
		Matcher m;
		if ((m = KICK.matcher(message)).matches())
		{
			api.post("clan/kick", new Kick(AwesomeClanPlugin.CLAN_NAME, m.group(2).trim(), m.group(1).trim()));
		}
		else if ((m = RECRUIT.matcher(message)).matches())
		{
			api.post("clan/recruit", new Recruit(AwesomeClanPlugin.CLAN_NAME, m.group(1).trim(), m.group(2).trim()));
		}
		else if ((m = DEPOSIT.matcher(message)).matches())
		{
			reportCoffer(m, "deposit");
		}
		else if ((m = WITHDRAW.matcher(message)).matches())
		{
			reportCoffer(m, "withdraw");
		}
	}

	private void reportCoffer(Matcher m, String type)
	{
		long amount;
		try
		{
			amount = Long.parseLong(m.group(2).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			log.debug("Bad coffer amount: {}", m.group(2));
			return;
		}

		// Everyone online reports the same broadcast. The server uses the
		// account ID to count it once.
		String accountId = AccountId.of(client.getAccountHash());
		api.post("clan/coffer", new CofferTransaction(AwesomeClanPlugin.CLAN_NAME, accountId, m.group(1).trim(), amount, type));
	}

	@Value
	private static class Kick
	{
		String clanName;
		String kickedName;
		String kickedBy;
	}

	@Value
	private static class Recruit
	{
		String clanName;
		String recruitedName;
		String recruitedBy;
	}

	@Value
	private static class CofferTransaction
	{
		String clanName;
		String accountId;
		String memberName;
		long amount;
		String type;
	}
}

package com.awesomeclan.live;

import com.awesomeclan.util.AccountId;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Collects XP and kill count changes and sends them every 15s while logged in.
 * It sends even when nothing changed, so the server knows you're still online.
 */
@Slf4j
public class LiveDataTracker
{
	// RuneLite names that differ from the hiscores names the server uses
	private static final Map<String, String> SKILL_NAME_OVERRIDES = Map.of("Runecraft", "Runecrafting");

	// "Your Zulrah kill count is: 412."
	// "Your completed Barrows Chests count is: 100."
	// "Your Chambers of Xeric completion count is: 5."
	private static final Pattern KILL_COUNT_PATTERN = Pattern.compile(
		"^Your (?:\\w+ )?(.+?) (?:\\w+ )?count is: ([0-9,]+)\\.$",
		Pattern.CASE_INSENSITIVE
	);

	@Inject
	private Client client;

	@Inject
	private LiveUploader uploader;

	private final Map<String, Integer> lastKnownSkillXp = new LinkedHashMap<>();
	private final Map<String, Integer> pendingSkillXp = new LinkedHashMap<>();
	private final Map<String, Integer> pendingBossKc = new LinkedHashMap<>();

	private long cachedAccountHash = -1;
	private String cachedAccountId;

	public void reset()
	{
		lastKnownSkillXp.clear();
		pendingSkillXp.clear();
		pendingBossKc.clear();
		uploader.reset();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		String name = canonicalSkillName(event.getSkill());
		int xp = event.getXp();

		Integer previous = lastKnownSkillXp.put(name, xp);
		// first event per skill is the login sync, and boosts/drains fire
		// this too without an xp change
		if (previous == null || previous == xp)
		{
			return;
		}

		pendingSkillXp.put(name, xp);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		Matcher matcher = KILL_COUNT_PATTERN.matcher(Text.removeTags(event.getMessage()));
		if (!matcher.matches())
		{
			return;
		}

		String bossName = matcher.group(1).trim();
		String count = matcher.group(2).replace(",", "");

		try
		{
			pendingBossKc.put(bossName, Integer.parseInt(count));
		}
		catch (NumberFormatException e)
		{
			log.debug("Could not parse kill count from chat message: {}", event.getMessage());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			flush(true);
			reset();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			// may no-op if the local player isn't set yet, the periodic flush covers it
			flush(false);
		}
	}

	public void flushPeriodic()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			flush(false);
		}
	}

	// Closing the client while logged in never goes through LOGIN_SCREEN
	public void flushOnShutdown()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			flush(true);
		}
	}

	private void flush(boolean loggedOut)
	{
		if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
		{
			return;
		}
		String rsn = client.getLocalPlayer().getName().trim();
		if (rsn.isEmpty())
		{
			return;
		}

		LivePayload payload = new LivePayload(
			rsn,
			accountId(),
			!loggedOut,
			loggedOut,
			new LinkedHashMap<>(pendingSkillXp),
			new LinkedHashMap<>(pendingBossKc)
		);

		uploader.upload(payload);
		pendingSkillXp.clear();
		pendingBossKc.clear();
	}

	// Checked every flush since the hash changes when you switch accounts
	// without restarting the client.
	private String accountId()
	{
		long hash = client.getAccountHash();
		if (hash != cachedAccountHash)
		{
			cachedAccountHash = hash;
			cachedAccountId = AccountId.of(hash);
		}
		return cachedAccountId;
	}

	private static String canonicalSkillName(Skill skill)
	{
		String name = skill.getName();
		return SKILL_NAME_OVERRIDES.getOrDefault(name, name);
	}
}

package com.awesomeclan.live;

import com.awesomeclan.AwesomeClanConfig;
import com.awesomeclan.api.ApiClient;
import com.awesomeclan.api.PluginTokens;
import java.io.IOException;
import java.util.List;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.Response;

/**
 * Each token belongs to one account and the server rejects the others, so
 * with several tokens configured we try them in turn until one is accepted,
 * then stick with it until logout.
 *
 * Only one request runs at a time. If another payload comes in meanwhile we
 * keep the newest one and send it after, so the logout payload doesn't get
 * dropped.
 */
@Slf4j
class LiveUploader
{
	@Inject
	private ApiClient api;

	@Inject
	private AwesomeClanConfig config;

	private boolean requestInFlight;
	private LivePayload queuedPayload;
	private String matchedToken;
	private int nextTokenIndex;

	synchronized void reset()
	{
		matchedToken = null;
		nextTokenIndex = 0;
		queuedPayload = null;
	}

	synchronized void upload(LivePayload payload)
	{
		if (requestInFlight)
		{
			queuedPayload = payload;
			return;
		}

		send(payload);
	}

	private void send(LivePayload payload)
	{
		String token = matchedToken != null ? matchedToken : nextCandidateToken();
		if (token == null)
		{
			return;
		}

		requestInFlight = true;
		api.newCall("live/submit", payload, token).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				log.warn("Live data submit failed", e);
				onRequestFinished();
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				response.close();
				synchronized (LiveUploader.this)
				{
					if (response.isSuccessful())
					{
						matchedToken = token;
					}
					else if (matchedToken == null)
					{
						nextTokenIndex++;
					}
				}

				if (!response.isSuccessful())
				{
					log.warn("Live data submit failed with HTTP {}", response.code());
				}
				onRequestFinished();
			}
		});
	}

	private synchronized void onRequestFinished()
	{
		requestInFlight = false;
		if (queuedPayload != null)
		{
			LivePayload next = queuedPayload;
			queuedPayload = null;
			send(next);
		}
	}

	private String nextCandidateToken()
	{
		List<String> tokens = PluginTokens.parse(config.pluginToken());
		if (tokens.isEmpty())
		{
			return null;
		}

		return tokens.get(nextTokenIndex % tokens.size());
	}
}

