package com.awesomeclan.api;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public final class PluginTokens
{
	private PluginTokens()
	{
	}

	public static List<String> parse(String raw)
	{
		if (raw == null)
		{
			return List.of();
		}

		return Arrays.stream(raw.split("\\r?\\n"))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.toList());
	}
}

package com.awesomeclan.api;

import com.awesomeclan.AwesomeClanConfig;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@Singleton
public class ApiClient
{
	private static final HttpUrl BASE_URL = HttpUrl.parse("https://api.awesomeclan.com/api/");
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private AwesomeClanConfig config;

	/**
	 * Fire-and-forget POST for clan-wide data (roster, kicks, coffer, ...).
	 * Any of the user's tokens proves they're in the clan, so this uses the
	 * first one. Does nothing if no token is set.
	 */
	public void post(String path, Object payload)
	{
		List<String> tokens = PluginTokens.parse(config.pluginToken());
		if (tokens.isEmpty())
		{
			return;
		}

		newCall(path, payload, tokens.get(0)).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				log.warn("POST {} failed", path, e);
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				response.close();
				if (!response.isSuccessful())
				{
					log.warn("POST {} failed with HTTP {}", path, response.code());
				}
			}
		});
	}

	public Call newCall(String path, Object payload, String token)
	{
		Request request = new Request.Builder()
			.url(BASE_URL.resolve(path))
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.header("Authorization", "Bearer " + token)
			.build();
		return okHttpClient.newCall(request);
	}
}

package com.awesomeclan.util;

import com.google.common.hash.HashCode;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import lombok.extern.slf4j.Slf4j;

/**
 * Hashed account ID, stable across name changes. Uses the same hash as Dink's
 * dinkAccountHash so the IDs line up with Dink's. Don't change the padding,
 * the server has these stored.
 */
@Slf4j
public final class AccountId
{
	private static final byte[] PADDING = "JennaRaidingDreamSeedZeroPercentOptionsForAnts!"
		.getBytes(StandardCharsets.UTF_8);

	private AccountId()
	{
	}

	/** Null before login (account hash is -1). */
	public static String of(long accountHash)
	{
		if (accountHash == -1)
		{
			return null;
		}

		MessageDigest digest;
		try
		{
			digest = MessageDigest.getInstance("SHA-224");
		}
		catch (NoSuchAlgorithmException e)
		{
			log.warn("SHA-224 unavailable", e);
			return null;
		}

		byte[] input = ByteBuffer.allocate(8 + PADDING.length)
			.putLong(accountHash)
			.put(PADDING)
			.array();
		return HashCode.fromBytes(digest.digest(input)).toString();
	}
}

